// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
        // Deposit some ETH
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool depositOk,) = address(c).call{value: depositAmount}("");
        vm.assume(depositOk);
        uint256 balanceBefore = c.balances(caller);
        // Attempt collect
        vm.prank(caller);
        try c.Collect(collectAmount) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter <= balanceBefore, "Balance increased after Collect");
        } catch {
            // If it reverts, nothing to check
            assertTrue(true);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

